            a: 'For regular use (4+ hours/day), build the workstation. A dedicated A40 48 GB on RunPod costs $0.44/hr — at 4 hours/day, that\'s ~$642/year. At 2026\'s inflated hardware prices, the ~$5,300 Recommended build now pays for itself in roughly 9–10 years at 4 hrs/day, or under 5 years at 8 hrs/day. For occasional use (under 2 hours/day), cloud is cheaper. See the payback table above for the full breakdown.',
